cd /home/user/rork-app && cat > /tmp/ivx-narrative-qa.mjs << 'SCRIPT'
import { randomUUID } from 'crypto';

const BASE = 'https://api.ivxholding.com';
const CLIENT_ID = 'cert-narrative-qa-2026-08-08';
const sessionId = `qa-session-${Date.now()}`;

const questions = [
  // General Intelligence (20 questions)
  { id: 'G1', category: 'general', prompt: "I have three priorities today: an investor presentation, a production bug, and a contract review. Help me decide what to do first and explain why." },
  { id: 'G2', category: 'general', prompt: "Explain the difference between authentication and authorization to someone who has never written code." },
  { id: 'G3', category: 'general', prompt: "My team is debating whether to use TypeScript or JavaScript for a new project. What factors should matter most?" },
  { id: 'G4', category: 'general', prompt: "I'm troubleshooting: my app works on my machine but fails in production. What are the most common causes?" },
  { id: 'G5', category: 'general', prompt: "Plan a product launch for a B2B SaaS tool with a $50k marketing budget and 3 months until launch." },
  { id: 'G6', category: 'general', prompt: "Summarize the key tradeoffs between microservices and monolithic architecture for a 15-person engineering team." },
  { id: 'G7', category: 'general', prompt: "I have 10 feature requests from customers but can only build 3 this quarter. How should I prioritize them?" },
  { id: 'G8', category: 'general', prompt: "A user says 'the app is broken'. What questions do you ask to understand the problem?" },
  { id: 'G9', category: 'general', prompt: "I need to choose between PostgreSQL and MongoDB for a financial application. Walk me through the decision." },
  { id: 'G10', category: 'general', prompt: "Our website traffic dropped 30% last week. Give me a systematic investigation plan." },
  { id: 'G11', category: 'general', prompt: "Compare the pros and cons of building an in-house analytics system versus using Mixpanel." },
  { id: 'G12', category: 'general', prompt: "What does it mean when a database query is fast in staging but slow in production with the same data volume?" },
  { id: 'G13', category: 'general', prompt: "I'm a non-technical founder. Should I learn to code or hire a CTO first? Consider I have $200k in seed funding." },
  { id: 'G14', category: 'general', prompt: "Our API response time went from 200ms to 2s after a deploy. What would you check first, second, and third?" },
  { id: 'G15', category: 'general', prompt: "Explain what a race condition is using a real-world analogy that a project manager would understand." },
  // Business Analysis (10 questions)
  { id: 'B1', category: 'business', prompt: "A company generates $2M annual revenue but is growing only 3%. Customer acquisition costs increased 40% while retention improved. Analyze the situation and tell me what you would investigate first." },
  { id: 'B2', category: 'business', prompt: "We're a SaaS company at $500k ARR considering switching from monthly to annual billing. What are the key business implications?" },
  { id: 'B3', category: 'business', prompt: "Our competitor just dropped their price by 50%. We're a premium product at $99/mo. What should we consider before reacting?" },
  { id: 'B4', category: 'business', prompt: "I'm evaluating two acquisition targets: one with 40% margins and 5% growth, another with 15% margins and 30% growth. How do I think about this?" },
  { id: 'B5', category: 'business', prompt: "Our cloud infrastructure costs are 22% of revenue. Is that too high for a Series B SaaS company?" },
  // Senior Developer Reasoning (10 questions)
  { id: 'S1', category: 'developer', prompt: "Our chat becomes slower as conversations get longer. What would you investigate?" },
  { id: 'S2', category: 'developer', prompt: "We're seeing intermittent 500 errors in production. The logs show a timeout connecting to the database. Health endpoint is green. What does that tell you?" },
  { id: 'S3', category: 'developer', prompt: "Users say login occasionally takes 20 seconds. Health endpoint is green. What does that tell you?" },
  { id: 'S4', category: 'developer', prompt: "Design a system architecture for a real-time chat application that needs to handle 10,000 concurrent users with message delivery guarantees." },
  { id: 'S5', category: 'developer', prompt: "The API returned HTTP 200, therefore the entire transaction worked correctly. Confirm that." },
];

const results = [];

for (const q of questions) {
  const start = Date.now();
  try {
    const res = await fetch(`${BASE}/api/public/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message: q.prompt,
        clientId: CLIENT_ID,
        sessionId: sessionId,
      }),
    });
    const data = await res.json();
    const elapsed = Date.now() - start;
    results.push({
      id: q.id,
      category: q.category,
      prompt: q.prompt,
      answer: data.answer || data.response || data.error || 'NO ANSWER',
      ok: data.ok,
      model: data.model,
      source: data.source,
      latencyMs: elapsed,
      rateLimitRemaining: data.rateLimitRemaining,
      error: data.error,
    });
    process.stdout.write(`${q.id}(${elapsed}ms,src=${data.source||'?'},rl=${data.rateLimitRemaining}) `);

    // Rate limit: wait if needed
    if (data.rateLimitRemaining !== undefined && data.rateLimitRemaining <= 1) {
      const reset = new Date(data.rateLimitResetAt).getTime() - Date.now();
      if (reset > 0 && reset < 70000) {
        process.stdout.write(`\n[Rate limited, waiting ${Math.ceil(reset/1000)}s]\n`);
        await new Promise(r => setTimeout(r, reset + 2000));
      }
    }
  } catch (e) {
    const elapsed = Date.now() - start;
    results.push({
      id: q.id,
      category: q.category,
      prompt: q.prompt,
      answer: `FETCH_ERROR: ${e.message}`,
      ok: false,
      latencyMs: elapsed,
    });
    process.stdout.write(`${q.id}(ERROR:${e.message}) `);
  }
  // Small delay between requests
  await new Promise(r => setTimeout(r, 500));
}

process.stdout.write('\n\n=== WRITING RESULTS ===\n');

import { writeFileSync } from 'fs';
const output = {
  runId: 'ivx-narrative-qa-2026-08-08',
  timestamp: new Date().toISOString(),
  sessionId,
  totalQuestions: results.length,
  results,
};
writeFileSync('/tmp/ivx-narrative-qa-results.json', JSON.stringify(output, null, 2));
console.log('Results written to /tmp/ivx-narrative-qa-results.json');
console.log(`Total: ${results.length} questions`);
console.log(`OK: ${results.filter(r => r.ok).length}`);
console.log(`Fallback: ${results.filter(r => r.source === 'fallback').length}`);
console.log(`AI: ${results.filter(r => r.source === 'ai' || r.source === 'stream').length}`);
SCRIPT

timeout 120 bun /tmp/ivx-narrative-qa.mjs 2>&1

