export function detectIVXConversationQuestion(message: string): IVXConversationType {
  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s+\-*/=.%]/g, ' ');
  const compact = text.replace(/\s+/g, ' ').trim();
